                if not math.isfinite(dy_i):
                    raise ValueError(
                        "binary_cross_entropy_with_logits backward"
                        " intermediate must be finite"
                    )
                dy.append(dy_i)
            contributions.append((parent_other, dy))
        return contributions

    return Tensor._make(
        out_data, True, (parent_self, parent_other), backward_fn
    )

